INSERT INTO "profiles" ("id","user_id","title","bio","avatar_url","cv_url","location","name") VALUES(3,1,'Web Developer','Halo! Saya Web Developer yang senang mengubah masalah bisnis menjadi aplikasi web yang sederhana dan andal. Saya peduli pada keseluruhan proses, mulai dari struktur data hingga pengalaman pengguna. Sebagai pembelajar cepat, saya selalu memahami masalah secara mendalam sebelum menulis kode, dan saat ini saya terbuka untuk peluang baru.','https://res.cloudinary.com/ddmtvnh6o/image/upload/v1793757827/portfolio/profiles/kj8wcricxgimhm1noqdt.png','https://drive.google.com/drive/folders/1LpNlTxMmldgXQEqqzXWX36uW547L44M7?usp=sharing',NULL,'Aditia Rizky Utama');
