INSERT INTO "projects" ("id","title","slug","description","thumbnail_url","demo_url","source_code_url","order_position","created_at","images") VALUES(6,'Parent Kanal Universitas Muria Kudus','parent-kanal',replace('Parent Kanal ("Kanal Untuk Orang Tua") adalah aplikasi web yang dikembangkan di Lembaga Sistem Informasi (LSI) Universitas Muria Kudus. Sistem ini memberi orang tua atau wali akses ke data akademik mahasiswa dalam satu tempat, tanpa harus datang ke kampus atau bertanya lewat perantara.\nDalam pengembangan sistem ini, saya mengerjakan front end mengguanan React JS dan mengintegrasikan data melalui Rest API yang sudah ada.','\n',char(10)),'https://res.cloudinary.com/ddmtvnh6o/image/upload/v1793783676/portfolio/projects/t8sarylnwq3dgc5dqy8j.png',NULL,NULL,0,'2026-11-04 09:13:54','["https://res.cloudinary.com/ddmtvnh6o/image/upload/v1793782175/portfolio/projects/jlzzzirkt6xft6hjiyli.png","https://res.cloudinary.com/ddmtvnh6o/image/upload/v1793783307/portfolio/projects/qqjbczjjlegmwm4c0rii.png","https://res.cloudinary.com/ddmtvnh6o/image/upload/v1793783307/portfolio/projects/rleyula1gk2ni2ph9ysj.png","https://res.cloudinary.com/ddmtvnh6o/image/upload/v1793783308/portfolio/projects/yfokswaepv7jwuepab81.png","https://res.cloudinary.com/ddmtvnh6o/image/upload/v1793783308/portfolio/projects/vzfkukp21bvhzmhntddc.png","https://res.cloudinary.com/ddmtvnh6o/image/upload/v1793783309/portfolio/projects/miv2gee2geee6p5wbfao.png"]');
